\begin{eqnarray}
R(t) = \frac{{\rm d}\mathbb{Q}_{\qinit}[X^t_0]}{{\rm d}\mathbb{P}_{\pinit}[X^t_0]}=  \frac{\qinit(X(0))}{\pinit(X(0))} \exp\left(\int^{t}_0 dt' \left[r_p(X(t'))-r_q(X(t'))\right] + \sum^{N(t)-1}_{i=1} \ln \frac{\ell_{X_{i-1}\rightarrow X_{i}}}{k_{X_{i-1}\rightarrow X_{i}}} \right), \label{eq:Radon} 
\end{eqnarray}
where 
\begin{eqnarray}
r_p(u) = \sum_{v\in \mathcal{X};v\neq u} k_{u\rightarrow v} \quad {\rm and} \quad r_q(u) = \sum_{v\in\mathcal{X};v\neq u} \ell_{u\rightarrow v} \label{eq:exitrates}
\end{eqnarray}  
are the escape rates out of the state $u\in\mathcal{X}$ corresponding to the measures $\mathbb{P}_{p^\ast}$ and $\mathbb{Q}_{q^\ast}$, respectively.     


If the two measures have the same escape rates, i.e.~$r_p(u)=r_q(u)$ for all $u\in\mathcal{X}$, then we obtain the simpler expression 
\begin{eqnarray}
